const D = { energy:.6, scale:1, density:.5, speed:1, hue:32, x:.5, y:.52, yaw:.42, lit:.5, style:'dusk', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving');

// ---- real-time crab down the canyon. blocks keyed on ABSOLUTE index -> never re-phases
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.13 + .14*K.intensity + .13*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.45 + .55*P.energy) * (.55 + .5*K.intensity) + bsm*.28;

// incommensurate drift = motion floor that never returns to the same pose
const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const W = u*.44*P.scale, HT = u*1.30*P.scale, BS = u*.80;
const NB = Math.round(6 + P.density*7);
const camZ = S.z*BS, camX = W*.20*dB*P.energy, camY = -(u*.26 + u*.05*dC*P.energy);
const yaw = .10 + .55*cl(P.yaw,0,1) + .05*dA*P.energy;   // != 0 -> TWO vanishing points
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.05;
const vcx = cl(P.x,.15,.85)*width, vcy = cl(P.y,.28,.78)*height;
const base = Math.floor(S.z);

// raking sun azimuth crawls on incommensurate rates -> which wall is lit changes over minutes
const sunAz = .8 + .95*Math.sin(K.t*.043) + .38*Math.sin(K.t*.101+2.0);
const sX = Math.sin(sunAz), sZ = Math.cos(sunAz);

// ---- projection + near-plane clip -------------------------------------------
const AX = new Float64Array(14), AY = new Float64Array(14), AZ = new Float64Array(14);
const BX = new Float64Array(18), BY = new Float64Array(18);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AX[i] = X*ca - Z*sa; AY[i] = Y; AZ[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZ[i], bz = AZ[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BX[m] = vcx + f*AX[i]/az; BY[m] = vcy + f*AY[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BX[m] = vcx + f*(AX[i]+(AX[j]-AX[i])*tt)/NEAR;
      BY[m] = vcy + f*(AY[i]+(AY[j]-AY[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BX[i], BY[i]); endShape(CLOSE);
  return true;
}

// ---- style tone tables ------------------------------------------------------
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
function skyC(s){
  if (paper) return [42, 4+5*s, 97-5*s];
  if (wire)  return [214, 66, 11+7*s];
  if (sty === 'noir')    return [0, 0, 22 + 62*Math.pow(s,1.7)];
  if (sty === 'thermal') return [252, 58, 5 + 13*s];
  return [(HU + 200*(1-Math.pow(s,2.0)))%360, 64 - 6*s, 11 + 58*Math.pow(s,2.3)*(.55+.55*gl)];
}
function grdC(s){
  if (paper) return [42, 6, 89 - 12*s];
  if (wire)  return [214, 60, 15 - 4*s];
  if (sty === 'noir')    return [0, 0, 24 - 13*s];
  if (sty === 'thermal') return [256, 54, 9 - 3*s];
  return [(HU+212)%360, 30 - 9*s, 26 - 13*s];
}
const FOG = skyC(.9), fogA = (paper||wire) ? .34 : .74;
function bldC(lam, tv, hz){
  const v = .16 + .74*lam + .10*tv;
  let c;
  if (paper)             c = [42, 7, 96 - 48*(1-v)];
  else if (wire)         c = [214, 62, 13 + 9*v];
  else if (sty==='noir') c = [0, 0, 4 + 76*Math.pow(v,1.5)];
  else if (sty==='thermal') c = [262 - 128*v, 62 - 18*v, 11 + 60*v];
  else c = [(HU+206)%360, 28 - 13*v + 7*tv, 9 + 52*v*(.6+.5*gl)];
  return mixc(c, FOG, hz*fogA);
}
function ink(a){
  if (wire)  stroke(190, 32, 100, a);
  else if (paper) stroke(32, 22, 15, a);
  else if (sty==='noir') stroke(0,0,96, a*.4);
  else if (sty==='thermal') stroke(30, 70, 90, a*.5);
  else stroke((HU+200)%360, 20, 88, a*.32);
}

// ---- sky + street ground (banded, not per-scanline) --------------------------
noStroke();
const nb2 = 34;
for (let i=0;i<nb2;i++){
  const s = i/(nb2-1), c = skyC(s);
  const jt = (fr(i*3.3)-.5)*(paper?2.2:1.4);
  fill(c[0], cl(c[1]+jt*2,0,100), cl(c[2]+jt,0,100));
  rect(0, (s*vcy)-1.5, width, vcy/nb2 + 3);
}
for (let i=0;i<nb2;i++){
  const s = i/(nb2-1), c = grdC(s);
  fill(c[0], c[1], cl(c[2] + (fr(i*7.1+40)-.5)*1.6, 0, 100));
  rect(0, vcy + s*(height-vcy) - 1.5, width, (height-vcy)/nb2 + 3);
}

// horizon glow pool (partial frame, never a flash)
if (!paper && !wire){
  push(); blendMode(ADD); noStroke();
  for (let i=4;i>=1;i--){
    fill(skyC(1)[0], 40, 100, 2.4 + 3.2*gl);
    ellipse(vcx - f*Math.tan(yaw), vcy, width*.55*i*.4, height*.16*i*.4);
  }
  pop(); blendMode(BLEND);
}

// ---- blocks, far -> near ----------------------------------------------------
strokeWeight(Math.max(1, u*.0016));
for (let k = base+NB-1; k >= base; k--){
  const hz = cl((k - S.z)/NB, 0, 1);
  for (let si=0; si<2; si++){
    const sgn = si ? 1 : -1;
    const g0 = .04 + .16*fr(k*3.1 + si*17.7);
    const z0 = (k+g0)*BS, z1 = (k+1-.06)*BS;
    const HB = HT*(.34 + .92*fr(k*5.7 + si*29.3));
    const dep = BS*(.55 + .55*fr(k*11.3 + si*7.1));
    const xi = sgn*W, xo = sgn*(W+dep);
    const tv = fr(k*2.3 + si*41.1);
    const lamW = cl(-sgn*sX, 0, 1), lamE = cl(-sZ, 0, 1);

    // street-facing face
    let c = bldC(lamW, tv, hz);
    if (wire) noFill(); else { noStroke(); fill(c[0], c[1], c[2], 100); }
    if (wire) ink(72);
    poly([xi,0,z0, xi,-HB,z0, xi,-HB,z1, xi,0,z1]);

    // near end face (the second vanishing point lives here)
    if (z0 > camZ + NEAR*1.2){
      const c2 = bldC(lamE, tv*.7+.2, hz);
      if (wire) { noFill(); ink(58); } else { noStroke(); fill(c2[0], c2[1], c2[2]*.86, 100); }
      poly([xi,0,z0, xo,0,z0, xo,-HB,z0, xi,-HB,z0]);
    }
    // parapet cap
    if (!wire){
      const c3 = bldC(cl(lamW*.5+.55,0,1), tv, hz); noStroke();
      fill(c3[0], c3[1]*.8, cl(c3[2]*1.22+4,0,96), 100);
      poly([xi,-HB,z0, xo,-HB,z0, xo,-HB-u*.012,z1, xi,-HB-u*.012,z1]);
    }

    // window bands — texture, not flat fill
    const nf2 = Math.min(10, Math.max(3, Math.floor(HB/(u*.085))));
    const fh = HB/nf2;
    if (k - base < 5 && !wire){
      for (let j=0;j<nf2;j++){
        const yb = -(j+.32)*fh, yt = -(j+.86)*fh;
        const r = fr(k*13.7 + j*5.9 + si*23.1);
        const fl = .5 + .5*Math.sin(K.t*(.21 + r*.5) + j*1.7 + k*2.3);
        const on = r < cl(P.lit,0,1)*(.4 + .5*gl);
        let wc;
        if (paper) wc = [42, 9, on ? 96 : 52 - 14*tv];
        else if (sty==='noir') wc = [0, 0, on ? cl(72+26*fl,0,99) : 5];
        else if (sty==='thermal') wc = on ? [22, 78, cl(62+34*fl,0,99)] : [252, 52, 14];
        else wc = on ? [(HU+8)%360, 52 - 16*fl, cl(48 + 46*fl*gl, 12, 97)] : [(HU+204)%360, 30, 5 + 6*tv];
        wc = mixc(wc, FOG, hz*fogA*.8);
        noStroke(); fill(wc[0], wc[1], wc[2], 100);
        poly([xi,yb,z0+BS*.05, xi,yt,z0+BS*.05, xi,yt,z1-BS*.05, xi,yb,z1-BS*.05]);
      }
    } else if (!wire){
      // far blocks: a single compressed tonal band keeps the silhouette from going flat
      const wc = mixc([(HU+204)%360, 26, 12], FOG, hz*fogA);
      noStroke(); fill(wc[0], wc[1], wc[2], 100);
      poly([xi,-HB*.1,z0, xi,-HB*.92,z0, xi,-HB*.92,z1, xi,-HB*.1,z1]);
    }

    // mullions / hatch — line texture over the face
    if ((paper || wire) && k - base < 6){
      ink(paper ? 40 : 74); noFill();
      const nc = 5;
      for (let j=1;j<nc;j++){
        const zz = z0 + (z1-z0)*j/nc;
        poly([xi,0,zz, xi,-HB,zz]);
      }
      for (let j=1;j<nf2;j++){
        const yy = -j*fh;
        poly([xi,yy,z0, xi,yy,z1]);
      }
    }
    // a couple of hot panes near the camera
    if (!paper && !wire && k - base < 4){
      const nh = 2;
      for (let j=0;j<nh;j++){
        const r = fr(k*17.3 + j*3.7 + si*9.1);
        if (r > .55) continue;
        const jf = Math.floor(r*nf2*2.2)%Math.max(1,nf2);
        const yb = -(jf+.32)*fh, yt = -(jf+.86)*fh;
        const zz = z0 + (z1-z0)*(.18 + .64*fr(k*19.1+j*11.3));
        push(); blendMode(ADD); noStroke();
        fill(sty==='thermal'?20:(HU+6)%360, 44, 100, cl(9 + 16*gl, 0, 34));
        poly([xi,yb,zz, xi,yt,zz, xi,yt,zz+BS*.10, xi,yb,zz+BS*.10]);
        pop(); blendMode(BLEND);
      }
    }
  }
}

// ---- road markings receding to the vanishing point ---------------------------
if (!wire){
  const dc = paper ? [42,10,74] : (sty==='noir' ? [0,0,62] : [(HU+8)%360, 22, 62]);
  noStroke();
  for (let k=base; k<base+NB+2; k++){
    const hz = cl((k - S.z)/(NB+2), 0, 1);
    const c = mixc(dc, FOG, hz*fogA*.9);
    fill(c[0], c[1], c[2], 100);
    poly([-u*.012, 0, k*BS+BS*.12, u*.012, 0, k*BS+BS*.12, u*.012, 0, k*BS+BS*.52, -u*.012, 0, k*BS+BS*.52]);
  }
  // kerbs
  for (let si=0; si<2; si++){
    const sgn = si ? 1 : -1;
    const c = mixc(paper?[42,8,80]:[(HU+206)%360, 18, 26], FOG, .38*fogA);
    fill(c[0], c[1], c[2], 100);
    poly([sgn*W*.88, 0, base*BS, sgn*W, 0, base*BS, sgn*W, 0, (base+NB)*BS, sgn*W*.88, 0, (base+NB)*BS]);
  }
}

// ---- wet reflection smear under the canyon (partial, low alpha) --------------
if (!paper && !wire){
  push(); blendMode(ADD); noStroke();
  for (let si=0; si<2; si++){
    const sgn = si ? 1 : -1;
    for (let i=0;i<3;i++){
      const zz = (base + 1 + i*1.7 + (S.z%1)*.4)*BS;
      fill(skyC(1)[0], 38, 100, 2.6 + 4.4*gl);
      poly([sgn*W*.92, 0, zz, sgn*W*.30, 0, zz, sgn*W*.30, 0, zz+BS*.55, sgn*W*.92, 0, zz+BS*.55]);
    }
  }
  pop(); blendMode(BLEND);
}

// ---- cached grain + vignette (texture over every flat fill) ------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/240));
  for (let i=0;i<N;i++){
    const gx = (Math.sin(i*12.9898)*43758.5453)%1, gy = (Math.sin(i*78.233+2.1)*43758.5453)%1;
    const px = Math.abs(gx)*width, py = Math.abs(gy)*height;
    const dk = ((Math.sin(i*3.17)*1000)%1) > 0 ? 1 : 0;
    g.fill(0,0, dk?100:0, paper ? 7 : 5);
    g.rect(px, py, 1.6, 1.6);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.085;
    g.fill(0,0,0, 1.0 + 3.6*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
